CREATE TYPE "VenueStatus" AS ENUM ('PENDING', 'APPROVED', 'REJECTED');
CREATE TYPE "PricingType" AS ENUM ('STANDARD', 'WEEKEND', 'PEAK');
CREATE TYPE "ComplaintStatus" AS ENUM ('OPEN', 'IN_PROGRESS', 'RESOLVED', 'REJECTED');
ALTER TABLE "Venue" ADD COLUMN "imageUrls" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "videoUrls" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "sportTypes" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "status" "VenueStatus" NOT NULL DEFAULT 'PENDING', ADD COLUMN "isActive" BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE "Court" ADD COLUMN "imageUrls" TEXT[] NOT NULL DEFAULT ARRAY[]::TEXT[], ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE TABLE "VenueOpeningHour" ("id" TEXT NOT NULL, "weekday" INTEGER NOT NULL, "opensAt" TEXT NOT NULL, "closesAt" TEXT NOT NULL, "isClosed" BOOLEAN NOT NULL DEFAULT false, "venueId" TEXT NOT NULL, CONSTRAINT "VenueOpeningHour_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VenueOpeningHour_venueId_weekday_key" ON "VenueOpeningHour"("venueId", "weekday");
ALTER TABLE "VenueOpeningHour" ADD CONSTRAINT "VenueOpeningHour_venueId_fkey" FOREIGN KEY ("venueId") REFERENCES "Venue"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "PricingRule" ("id" TEXT NOT NULL, "type" "PricingType" NOT NULL, "pricePerHour" DECIMAL(12,2) NOT NULL, "weekday" INTEGER, "startsAt" TEXT NOT NULL, "endsAt" TEXT NOT NULL, "courtId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "PricingRule_pkey" PRIMARY KEY ("id"));
CREATE INDEX "PricingRule_courtId_type_weekday_idx" ON "PricingRule"("courtId", "type", "weekday");
ALTER TABLE "PricingRule" ADD CONSTRAINT "PricingRule_courtId_fkey" FOREIGN KEY ("courtId") REFERENCES "Court"("id") ON DELETE CASCADE ON UPDATE CASCADE;
CREATE TABLE "MaintenanceBlock" ("id" TEXT NOT NULL, "startAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3) NOT NULL, "reason" TEXT NOT NULL, "courtId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "MaintenanceBlock_pkey" PRIMARY KEY ("id"));
CREATE INDEX "MaintenanceBlock_courtId_startAt_endAt_idx" ON "MaintenanceBlock"("courtId", "startAt", "endAt");
ALTER TABLE "MaintenanceBlock" ADD CONSTRAINT "MaintenanceBlock_courtId_fkey" FOREIGN KEY ("courtId") REFERENCES "Court"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "Booking" ADD COLUMN "notes" TEXT, ADD COLUMN "cancelReason" TEXT, ADD COLUMN "cancelledAt" TIMESTAMP(3), ADD COLUMN "cancelledById" TEXT;
CREATE INDEX "Booking_status_startAt_idx" ON "Booking"("status", "startAt");
DROP INDEX IF EXISTS "Review_userId_courtId_key";
ALTER TABLE "Review" ADD COLUMN "bookingId" TEXT, ADD COLUMN "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP;
CREATE UNIQUE INDEX "Review_bookingId_key" ON "Review"("bookingId");
CREATE INDEX "Review_courtId_idx" ON "Review"("courtId");
CREATE INDEX "Review_userId_idx" ON "Review"("userId");
ALTER TABLE "Review" ADD CONSTRAINT "Review_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE SET NULL ON UPDATE CASCADE;
CREATE TABLE "Complaint" ("id" TEXT NOT NULL, "bookingId" TEXT NOT NULL, "complainantId" TEXT NOT NULL, "subject" TEXT NOT NULL, "description" TEXT NOT NULL, "status" "ComplaintStatus" NOT NULL DEFAULT 'OPEN', "resolution" TEXT, "assignedAdminId" TEXT, "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Complaint_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Complaint_bookingId_idx" ON "Complaint"("bookingId");
CREATE INDEX "Complaint_complainantId_idx" ON "Complaint"("complainantId");
CREATE INDEX "Complaint_status_idx" ON "Complaint"("status");
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_bookingId_fkey" FOREIGN KEY ("bookingId") REFERENCES "Booking"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_complainantId_fkey" FOREIGN KEY ("complainantId") REFERENCES "User"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "Complaint" ADD CONSTRAINT "Complaint_assignedAdminId_fkey" FOREIGN KEY ("assignedAdminId") REFERENCES "User"("id") ON DELETE SET NULL ON UPDATE CASCADE;
